config.command:
set -euo pipefail
set -- {{ execution_path }}; WS="${1:-}"
set -- {{ exclude_packages }}; EXCL="$*"
case "$EXCL" in *"{{"*) EXCL="" ;; esac

ST="$WS/.git/dep-update"
FE="$(cat "$ST/fe_abs")"
# npm outdated exits with 1 as soon as something is outdated - that is the normal case here.
(cd "$FE" && npm outdated --json > "$ST/outdated.json" 2> "$ST/outdated.err") || true

ST="$ST" EXCL="$EXCL" python3 - <<'PY'
import json, os, re, subprocess

st = os.environ["ST"]
fe = open(st + "/fe_abs").read().strip()
fe_rel = open(st + "/fe_rel").read().strip()
pkg = json.load(open(fe + "/package.json", encoding="utf-8"))
try:
    outdated = json.load(open(st + "/outdated.json")) or {}
except ValueError:
    raise SystemExit("npm outdated returned no JSON:\n" + open(st + "/outdated.err").read()[-800:])
excl = {e for e in re.split(r"[\s,]+", os.environ.get("EXCL", "")) if e}
SECTIONS = ("dependencies", "devDependencies", "optionalDependencies")


def ver(v):
    m = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", v or "")
    return tuple(map(int, m.groups())) if m else None


def breaking(a, b):
    # semver: a major change, for 0.x already a minor change
    return a[0] != b[0] or (a[0] == 0 and a[1] != b[1])


def spec(name):
    for s in SECTIONS:
        if name in (pkg.get(s) or {}):
            return pkg[s][name]
    return None


minor, majors, skipped = [], {}, []
for name, info in sorted(outdated.items()):
    if isinstance(info, list):
        info = info[0]
    cur, wanted, latest = ver(info.get("current")), ver(info.get("wanted")), ver(info.get("latest"))
    sp = spec(name)
    if name in excl:
        skipped.append((name, "excluded (exclude_packages)")); continue
    if sp is None:
        skipped.append((name, "not a direct dependency in package.json")); continue
    if not re.fullmatch(r"[\^~]?\d+\.\d+\.\d+", sp):
        skipped.append((name, f"version spec '{sp}' is not changed automatically")); continue
    if not cur or not latest:
        skipped.append((name, "version not readable (not installed or a pre-release)")); continue
    safe = latest if not breaking(cur, latest) else (
        wanted if wanted and wanted > cur and not breaking(cur, wanted) else None)
    if not safe or safe <= cur:
        # Pinned exactly/narrowly: npm outdated does not know the newest version within the same major.
        try:
            r = subprocess.run(["npm", "view", "--json", f"{name}@^{info['current']}", "version"],
                               cwd=fe, capture_output=True, text=True, timeout=90)
            found = json.loads(r.stdout) if r.stdout.strip() else []
        except (subprocess.SubprocessError, ValueError):
            found = []
        cands = [v for v in map(ver, found if isinstance(found, list) else [found]) if v]
        safe = max(cands) if cands else None
    if safe and safe > cur:
        minor.append({"name": name, "from": info["current"], "to": ".".join(map(str, safe))})
    if breaking(cur, latest):
        majors[name] = {"name": name, "from": info["current"], "to": info["latest"]}

# Major groups: what only works together is tried together.
parent = {n: n for n in majors}


def find(n):
    while parent[n] != n:
        n = parent[n]
    return n


def union(a, b):
    parent[find(a)] = find(b)


names = set(majors)
for n in sorted(names):
    if n.startswith("@types/"):                      # @types/x  <-> x
        base = n[len("@types/"):]
        base = "@" + base.replace("__", "/") if "__" in base else base
        if base in names:
            union(n, base)
    if n.startswith("@"):                            # @eslint/js <-> eslint, same scope
        scope = n[1:].split("/")[0]
        if scope in names:
            union(n, scope)
        for m in names:
            if m != n and m.startswith("@" + scope + "/"):
                union(n, m)
    try:                                             # required peers of the target version
        r = subprocess.run(["npm", "view", "--json", f"{n}@{majors[n]['to']}"],
                           cwd=fe, capture_output=True, text=True, timeout=90)
        manifest = json.loads(r.stdout) if r.stdout.strip() else {}
        if isinstance(manifest, list):
            manifest = manifest[-1] if manifest else {}
    except (subprocess.SubprocessError, ValueError):
        manifest = {}
    optional = {p for p, meta in (manifest.get("peerDependenciesMeta") or {}).items()
                if isinstance(meta, dict) and meta.get("optional")}
    for p in manifest.get("peerDependencies") or {}:
        if p in names and p not in optional:
            union(n, p)

groups = {}
for n in sorted(names):
    groups.setdefault(find(n), []).append(majors[n])
keyed = {}
for members in groups.values():
    lead = min((m["name"] for m in members), key=lambda x: (x.startswith("@types/"), len(x), x))
    keyed[lead.replace("/", "__")] = members

json.dump({"minor": minor, "groups": keyed, "skipped": skipped},
          open(st + "/plan.json", "w"), indent=2, ensure_ascii=False)
with open(st + "/major_keys.txt", "w") as f:
    f.writelines(k + "\n" for k in sorted(keyed))

print(f"## Update plan for {fe_rel}\n")
if not minor and not keyed:
    print("Everything is up to date - there is nothing to update.")
if minor:
    print(f"### Patch/minor ({len(minor)}) - bundled, halved on red")
    for m in minor:
        print(f"- {m['name']}: {m['from']} -> {m['to']}")
    print()
if keyed:
    print(f"### Major ({len(keyed)} groups) - each group checked on its own")
    for k in sorted(keyed):
        print(f"- [{k}] " + ", ".join(f"{m['name']} {m['from']} -> {m['to']}" for m in keyed[k]))
    print()
if skipped:
    print(f"### Not touched ({len(skipped)})")
    for n, why in skipped:
        print(f"- {n}: {why}")
PY
